package bd.hscsolution.catalog.entity;
import jakarta.persistence.*; import java.util.UUID;
@Entity @Table(name="mcq_option",uniqueConstraints={@UniqueConstraint(columnNames={"question_version_id","option_key"}),@UniqueConstraint(columnNames={"question_version_id","display_order"})}) public class McqOption { @Id @GeneratedValue(strategy=GenerationType.UUID) public UUID id; @ManyToOne(fetch=FetchType.LAZY,optional=false) @JoinColumn(name="question_version_id") public QuestionVersion questionVersion; @Column(name="option_key",nullable=false,length=5) public String optionKey; @Column(name="option_text",nullable=false,columnDefinition="text") public String optionText; @Column(name="is_correct",nullable=false) public boolean correct; @Column(name="display_order",nullable=false) public int displayOrder; }
